    #[test]
    fn relay_namespace_prefix_avoids_the_fd_closing_legacy_wrapper() {
        let entry = Path::new("/proc/self/fd/201");
        let spec = Path::new("/owned/cell.json");
        let legacy = development_namespace_command("owned-net", entry, spec, false);
        let expected_legacy = [
            "netns", "exec", "owned-net", "unshare", "--mount", "--pid", "--mount-proc",
            "--ipc", "--uts", "--fork", "--kill-child=TERM", "--forward-signals",
            "--propagation=private", "/proc/self/fd/201", "development-enter", "--spec", "/owned/cell.json",
        ];
        assert_eq!(legacy.get_program(), OsStr::new("ip"));
        assert_eq!(legacy.get_args().collect::<Vec<_>>(),
            expected_legacy.iter().map(OsStr::new).collect::<Vec<_>>());
        let relay = development_namespace_command("owned-net", entry, spec, true);
        let mut expected_relay = expected_legacy.to_vec();
        expected_relay[3] = "/usr/bin/unshare";
        expected_relay.retain(|value| *value != "--forward-signals");
        assert_eq!(relay.get_program(), OsStr::new("/usr/bin/ip"));
        assert_eq!(relay.get_args().collect::<Vec<_>>(),
            expected_relay.iter().map(OsStr::new).collect::<Vec<_>>());
    }

    #[test]
    fn cleanup_failure_repeats_until_the_owned_runtime_is_removed() {
        let directory = tempfile::tempdir().unwrap();
        let spec = owned_cleanup_test_spec(directory.path());
        fs::create_dir(&spec.runtime_dir).unwrap();
        let blocker = spec.runtime_dir.join("android-cmdline");
        fs::create_dir(&blocker).unwrap();
        let mut child = std::process::Command::new("/bin/true").spawn().unwrap();
        assert!(child.wait().unwrap().success());
        let mut cell = DevelopmentCell::from_owned_child_for_test(spec.clone(), child);
        for _ in 0..3 {
            assert!(cell.try_wait().is_err());
            assert!(cell.wait().is_err());
            assert!(cell.stop().is_err());
            assert!(!cell.cleaned);
            assert!(blocker.is_dir());
        }
        fs::remove_dir(&blocker).unwrap();
        cell.stop().unwrap();
        assert!(cell.cleaned);
        assert!(!spec.runtime_dir.exists());
        assert!(cell.try_wait().unwrap().unwrap().success());
        cell.stop().unwrap();
    }

